/** 状態ストリーミングの接続を要求する。 */
export interface WatchStateRequest {
  /** 画面が選んだ更新間隔（0 は要求なし） */
  refreshRate: RefreshRate;
  /** 画面の識別子 */
  screen: string;
  /** 試行番号 */
  attempt: number;
}

/**
 * 問い合わせへの回答を要求する。
 *
 * 回答は、判断待ちの一覧（GetPendingDecisions、WatchState）にある問い合わせにだけ送る。一覧に無い
 * inquiry_id は NOT_FOUND で断る。goal_id を指定したときは、一覧の判断待ちが持つゴールと照合し、
 * 食い違えば takt へ送らずに FAILED_PRECONDITION で断る。断られたら、一覧を取得し直してから
 * やり直す。
 */
export interface AnswerInquiryRequest {
  /** サーバー */
  serverId: string;
  /** プロジェクト */
  project: string;
  /** ゴール ID（省略すると判断待ちの一覧から引き当てる。指定するなら一覧のゴールと同じ値。ゴールに属さない問い合わせには回答できない） */
  goalId?:
    | string
    | undefined;
  /** 問い合わせの識別子（判断待ちの inquiry_id） */
  inquiryId: string;
  /** 自由記述または選択肢の回答（質問への回答で使う） */
  text?:
    | string
    | undefined;
  /** 作業の依頼への回答（operation_request で使う） */
  report?:
    | OperationAnswerReport
    | undefined;
  /** 重複を防ぐ鍵（省略可） */
  idempotencyKey?: string | undefined;
}

/** 問い合わせへの回答への応答を表す。 */
export interface AnswerInquiryResponse {
  /** 受け付けた回答の対象の識別子 */
  inquiryId: string;
}

/** プルリクエストのマージの承認を要求する。 */
export interface ApproveGoalMergeRequest {
  /** サーバー */
  serverId: string;
  /** プロジェクト */
  project: string;
  /** ゴール ID */
  goalId: string;
  /** プルリクエストの番号 */
  prNumber: number;
  /** "prepare" なら準備まで、"merge" ならマージまで行う */
  until: string;
  /** 重複を防ぐ鍵（省略可） */
  idempotencyKey?: string | undefined;
}

/** プルリクエストのマージの承認への応答を表す。 */
export interface ApproveGoalMergeResponse {
  /** 依頼したタスク名 */
  taskName: string;
  /** 使うワークフロー */
  workflow: string;
}

/**
 * ゴール登録の承認を要求する。
 *
 * revision は、判断待ちの一覧（GetPendingDecisions、WatchState、ListGoalRegistrationProposals）に
 * ある承認待ちと照合する。一覧に無い revision と、接続先の設定が変わる前に読んだ一覧の revision は、
 * takt へ送らずに FAILED_PRECONDITION で断る。断られたら、一覧を取得し直してからやり直す。
 */
export interface ApproveGoalRegistrationRequest {
  /** サーバー */
  serverId: string;
  /** プロジェクト */
  project: string;
  /** 承認待ちの revision */
  revision: number;
  /** 重複を防ぐ鍵（省略可） */
  idempotencyKey?: string | undefined;
}

/** ゴール登録の承認への応答を表す。 */
export interface ApproveGoalRegistrationResponse {
  /** 承認した revision */
  revision: number;
  /** 登録されたゴールの ID */
  goalId: string;
}

/** ゴール登録の却下を要求する。revision の照合は ApproveGoalRegistrationRequest と同じ。 */
export interface RejectGoalRegistrationRequest {
  /** サーバー */
  serverId: string;
  /** プロジェクト */
  project: string;
  /** 却下する承認待ちの revision */
  revision: number;
  /** 重複を防ぐ鍵（省略可） */
  idempotencyKey?: string | undefined;
}

/** ゴール登録の却下への応答を表す。 */
export interface RejectGoalRegistrationResponse {
  /** 却下した revision */
  revision: number;
}

/** ゴール登録の承認待ちを表す。判断待ちの一覧へ表示できる形にする。 */
export interface GoalRegistrationProposal {
  /** 承認待ちの revision */
  revision: number;
  /** サーバー */
  serverId: string;
  /** プロジェクト */
  project: string;
  /** 本文（提案の要約） */
  body: string;
  /** 提案の対象プロジェクトのディレクトリ */
  repositoryDirectory: string;
}

/** ゴール登録の承認待ちの取得を要求する。 */
export interface ListGoalRegistrationProposalsRequest {
  /** サーバー */
  serverId: string;
  /** プロジェクト */
  project: string;
}

/** ゴール登録の承認待ちの取得への応答を表す。 */
export interface ListGoalRegistrationProposalsResponse {
  /** 承認待ち（無ければ空） */
  proposals: GoalRegistrationProposal[];
}

function createBaseServer(): Server {
  return { serverId: "", name: "", kind: "", connected: false, lastReadAt: undefined, writeOnly: false };
}

export const Server: MessageFns<Server> = {
  encode(message: Server, writer: BinaryWriter = new BinaryWriter()): BinaryWriter {
    if (message.serverId !== "") {
      writer.uint32(10).string(message.serverId);
    }
    if (message.name !== "") {
      writer.uint32(18).string(message.name);
    }
    if (message.kind !== "") {
      writer.uint32(26).string(message.kind);
    }
    if (message.connected !== false) {
      writer.uint32(32).bool(message.connected);
    }
    if (message.lastReadAt !== undefined) {
      Timestamp.encode(toTimestamp(message.lastReadAt), writer.uint32(42).fork()).join();
    }
    if (message.writeOnly !== false) {
      writer.uint32(56).bool(message.writeOnly);
    }
    return writer;
  },

  decode(input: BinaryReader | Uint8Array, length?: number): Server {
    const reader = input instanceof BinaryReader ? input : new BinaryReader(input);
    const previousRecursionDepth = (reader as any).__tsProtoDecodeDepth ?? 0;
    if (previousRecursionDepth >= 100) {
      throw new globalThis.Error("protobuf decode recursion limit exceeded");
    }
    (reader as any).__tsProtoDecodeDepth = previousRecursionDepth + 1;
    try {
      const end = length === undefined ? reader.len : reader.pos + length;
      const message = createBaseServer();
      while (reader.pos < end) {
        const tag = reader.uint32();
        switch (tag >>> 3) {
          case 1: {
            if (tag !== 10) {
              break;
            }

            message.serverId = reader.string();
            continue;
          }
          case 2: {
            if (tag !== 18) {
              break;
            }

            message.name = reader.string();
            continue;
          }
          case 3: {
            if (tag !== 26) {
              break;
            }

            message.kind = reader.string();
            continue;
          }
          case 4: {
            if (tag !== 32) {
              break;
            }

            message.connected = reader.bool();
            continue;
          }
          case 5: {
            if (tag !== 42) {
              break;
            }

            message.lastReadAt = fromTimestamp(Timestamp.decode(reader, reader.uint32()));
            continue;
          }
          case 7: {
            if (tag !== 56) {
              break;
            }

            message.writeOnly = reader.bool();
            continue;
          }
        }
        if ((tag & 7) === 4 || tag === 0) {
          break;
        }
        reader.skip(tag & 7);
      }
      return message;
    } finally {
      (reader as any).__tsProtoDecodeDepth = previousRecursionDepth;
    }
  },

  fromJSON(object: any): Server {
    return {
      serverId: isSet(object.serverId)
        ? globalThis.String(object.serverId)
        : isSet(object.server_id)
        ? globalThis.String(object.server_id)
        : "",
      name: isSet(object.name) ? globalThis.String(object.name) : "",
      kind: isSet(object.kind) ? globalThis.String(object.kind) : "",
      connected: isSet(object.connected) ? globalThis.Boolean(object.connected) : false,
      lastReadAt: isSet(object.lastReadAt)
        ? fromJsonTimestamp(object.lastReadAt)
        : isSet(object.last_read_at)
        ? fromJsonTimestamp(object.last_read_at)
        : undefined,
      writeOnly: isSet(object.writeOnly)
        ? globalThis.Boolean(object.writeOnly)
        : isSet(object.write_only)
        ? globalThis.Boolean(object.write_only)
        : false,
    };
  },

  toJSON(message: Server): unknown {
    const obj: any = {};
    if (message.serverId !== "") {
      obj.serverId = message.serverId;
    }
    if (message.name !== "") {
      obj.name = message.name;
    }
    if (message.kind !== "") {
      obj.kind = message.kind;
    }
    if (message.connected !== false) {
      obj.connected = message.connected;
    }
    if (message.lastReadAt !== undefined) {
      obj.lastReadAt = message.lastReadAt.toISOString();
    }
    if (message.writeOnly !== false) {
      obj.writeOnly = message.writeOnly;
    }
    return obj;
  },

  create<I extends Exact<DeepPartial<Server>, I>>(base?: I): Server {
    return Server.fromPartial(base ?? ({} as any));
  },
  fromPartial<I extends Exact<DeepPartial<Server>, I>>(object: I): Server {
    const message = createBaseServer();
    message.serverId = object.serverId ?? "";
    message.name = object.name ?? "";
    message.kind = object.kind ?? "";
    message.connected = object.connected ?? false;
    message.lastReadAt = object.lastReadAt ?? undefined;
    message.writeOnly = object.writeOnly ?? false;
    return message;
  },
};

